python3 - <<'PY'
import openpyxl, zipfile, os, sys, re
from openpyxl.utils import get_column_letter
p='/root/output/result.xlsx'
wb=openpyxl.load_workbook(p, data_only=False)
ws=wb['Task']
errors=[]
# no new sheets
if wb.sheetnames != ['Task','Data']:
    errors.append(f'Unexpected sheets: {wb.sheetnames}')
# formulas checks
def expect(cell, formula):
    v=ws[cell].value
    if v != formula:
        errors.append(f'{cell}: expected {formula}, got {v}')
# lookup 90 cells
lookup_count=0
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            col=get_column_letter(c)
            expected=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
            v=ws.cell(r,c).value
            if not (isinstance(v,str) and v.startswith('=INDEX(') and 'Data!' in v):
                errors.append(f'{col}{r} not INDEX/MATCH Data formula: {v}')
            if v != expected:
                errors.append(f'{col}{r} formula mismatch: {v} != {expected}')
            lookup_count += 1
# arithmetic formulas H35:L40
arith_count=0
for r in range(35,41):
    off=r-35
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=({col}{12+off}-{col}{19+off})/{col}{26+off}*100'
        if ws.cell(r,c).value != expected:
            errors.append(f'{col}{r} arithmetic mismatch: {ws.cell(r,c).value} != {expected}')
        arith_count += 1
# stats
for c in range(8,13):
    col=get_column_letter(c)
    expected_by_row={
        42:f'=MIN({col}35:{col}40)',
        43:f'=MAX({col}35:{col}40)',
        44:f'=MEDIAN({col}35:{col}40)',
        45:f'=AVERAGE({col}35:{col}40)',
        46:f'=PERCENTILE({col}35:{col}40,0.25)',
        47:f'=PERCENTILE({col}35:{col}40,0.75)',
        50:f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)',
    }
    for r,exp in expected_by_row.items():
        if ws.cell(r,c).value != exp:
            errors.append(f'{col}{r} mismatch: {ws.cell(r,c).value} != {exp}')
# untouched non-target formulas labels? ensure target only? We can compare source workbook for non-target cells.
src='/root/data/workbook.xlsx'
swb=openpyxl.load_workbook(src, data_only=False)
sws=swb['Task']
targets=set()
for start,end in [(12,17),(19,24),(26,31),(35,40),(42,47)]:
    for r in range(start,end+1):
        for c in range(8,13): targets.add((r,c))
for c in range(8,13): targets.add((50,c))
for row in range(1, ws.max_row+1):
    for col in range(1, ws.max_column+1):
        if (row,col) not in targets and ws.cell(row,col).value != sws.cell(row,col).value:
            errors.append(f'Non-target cell changed {get_column_letter(col)}{row}: {sws.cell(row,col).value} -> {ws.cell(row,col).value}')
# zip no macros/vba/external links
with zipfile.ZipFile(p) as z:
    names=z.namelist()
    vba=[n for n in names if n.endswith('vbaProject.bin') or 'vba' in n.lower()]
    ext=[n for n in names if n.startswith('xl/externalLinks/')]
    if vba: errors.append('VBA/macro parts present: '+str(vba))
    if ext: errors.append('External link parts present: '+str(ext))
print('Validation summary:')
print('  workbook:', p)
print('  size:', os.path.getsize(p))
print('  sheets:', wb.sheetnames)
print('  lookup formula cells checked:', lookup_count)
print('  arithmetic formula cells checked:', arith_count)
print('  stats/weighted formula cells checked:', 35)
print('  no macros/VBA:', True)
print('  no external links:', True)
print('  non-target Task cells unchanged: checked')
print('\nSample formulas after reopen:')
for cell in ['H12','I12','L17','H19','L24','H26','L31','H35','I36','L40','H42','I43','J44','K45','L46','H47','H50','L50']:
    print(f'  {cell}: {ws[cell].value}')
if errors:
    print('\nVALIDATION FAILED')
    for e in errors[:50]: print('ERROR:', e)
    if len(errors)>50: print('... more errors', len(errors)-50)
    sys.exit(1)
print('\nVALIDATION PASSED')
